contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address receiver, uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= 0, "");

        uint cBefore = address(c).balance;
        uint tBefore = address(this).balance;

        bool reverted;
        c.sendTo(receiver, amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint cAfter = address(c).balance;
        uint tAfter = address(this).balance;

        assert(reverted || ((cBefore >= cAfter && cBefore - cAfter == amount) && (receiver != address(this) || (tAfter >= tBefore && tAfter - tBefore == amount))));
    }

    receive() external payable {}
}

